  const [active] = useState();

  return (
    <main>
      <div className="game-container">
        <PlayerInfo IName="Player 1" symbol="X" />
        <PlayerInfo IName="Player 2" symbol="O" />
      </div>
      <div className="game-board">
        <GameBoard />
      </div>
    </main>
  );
}

export default App;
